CREATE TYPE "GroupActivationReviewStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');
ALTER TABLE "borrower_groups" ADD COLUMN "officerId" TEXT, ADD COLUMN "createdByUserId" TEXT;
CREATE TABLE "group_snapshots" ("id" TEXT NOT NULL, "snapshotNumber" VARCHAR(50) NOT NULL, "reason" VARCHAR(120) NOT NULL, "memberIds" TEXT[], "capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "isSampleData" BOOLEAN NOT NULL DEFAULT false, "groupId" TEXT NOT NULL, CONSTRAINT "group_snapshots_pkey" PRIMARY KEY ("id"));
CREATE TABLE "group_documents" ("id" TEXT NOT NULL, "documentNumber" VARCHAR(80) NOT NULL, "type" VARCHAR(50) NOT NULL, "reference" VARCHAR(255) NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "status" VARCHAR(30) NOT NULL, "isPrivate" BOOLEAN NOT NULL DEFAULT true, "isSampleData" BOOLEAN NOT NULL DEFAULT false, "groupId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "group_documents_pkey" PRIMARY KEY ("id"));
CREATE TABLE "group_activation_reviews" ("id" TEXT NOT NULL, "reviewNumber" VARCHAR(50) NOT NULL, "status" "GroupActivationReviewStatus" NOT NULL DEFAULT 'PENDING', "requestReason" VARCHAR(500) NOT NULL, "requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "decisionReason" VARCHAR(500), "decidedAt" TIMESTAMP(3), "isSampleData" BOOLEAN NOT NULL DEFAULT false, "groupId" TEXT NOT NULL, "requestedByUserId" TEXT NOT NULL, "decidedByUserId" TEXT, CONSTRAINT "group_activation_reviews_pkey" PRIMARY KEY ("id"));
CREATE TABLE "group_membership_changes" ("id" TEXT NOT NULL, "eventNumber" VARCHAR(50) NOT NULL, "action" VARCHAR(30) NOT NULL, "effectiveDate" TIMESTAMP(3) NOT NULL, "reason" VARCHAR(500) NOT NULL, "borrowerId" TEXT NOT NULL, "recordedByUserId" TEXT NOT NULL, "groupId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "group_membership_changes_pkey" PRIMARY KEY ("id"));
